-- TEAM TRUMAN spare-parts inventory schema for Supabase PostgreSQL
-- Run once in Supabase SQL Editor as project owner. Never expose service-role credentials.
create extension if not exists pgcrypto;
create type public.workshop_role as enum ('workshop_admin','inventory_manager','storekeeper','technician','auditor');
create table if not exists public.workshops(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,created_at timestamptz not null default now());
create table if not exists public.workshop_memberships(id uuid primary key default gen_random_uuid(),workshop_id uuid not null references public.workshops(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.workshop_role not null default 'technician',active boolean not null default true,created_at timestamptz not null default now(),unique(workshop_id,user_id));
create table if not exists public.parts(id uuid primary key default gen_random_uuid(),workshop_id uuid not null references public.workshops(id) on delete cascade,sku text not null,name text not null,description text,category text,current_stock integer not null default 0 check(current_stock>=0),unit_cost numeric(14,2) not null default 0 check(unit_cost>=0),bin_location text,supplier_name text,supplier_contact text,avg_daily_demand numeric(12,3) not null default 0 check(avg_daily_demand>=0),lead_time_days integer not null default 0 check(lead_time_days>=0),safety_stock integer not null default 0 check(safety_stock>=0),abc_class text not null default 'C' check(abc_class in ('A','B','C')),xyz_class text not null default 'Z' check(xyz_class in ('X','Y','Z')),minimum_order_qty integer not null default 0 check(minimum_order_qty>=0),target_stock_level integer check(target_stock_level is null or target_stock_level>=0),manufacturer_reference text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workshop_id,sku));
create table if not exists public.job_cards(id uuid primary key default gen_random_uuid(),workshop_id uuid not null references public.workshops(id) on delete cascade,job_number text not null,vehicle_identifier text not null,vehicle_model text,technician_identifier text not null,customer_reference text,work_description text not null,card_type text not null check(card_type in ('Full','Provisional')),status text not null check(status in ('Pending Approval','Open','Closed','Rejected')),created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,rejection_reason text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workshop_id,job_number),check((card_type='Full' and status in ('Open','Closed')) or card_type='Provisional'));
create table if not exists public.purchase_orders(id uuid primary key default gen_random_uuid(),workshop_id uuid not null references public.workshops(id) on delete cascade,order_number text not null,part_id uuid not null references public.parts(id),supplier_name text not null,ordered_qty integer not null check(ordered_qty>0),received_qty integer not null default 0 check(received_qty>=0 and received_qty<=ordered_qty),expected_arrival_date date,reference_number text,notes text,status text not null default 'Ordered' check(status in ('Ordered','Arrived','Received','Cancelled')),created_by uuid not null references auth.users(id),arrived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workshop_id,order_number));
create table if not exists public.stock_movements(id uuid primary key default gen_random_uuid(),workshop_id uuid not null references public.workshops(id) on delete cascade,part_id uuid not null references public.parts(id),sku text not null,part_name text not null,movement_type text not null check(movement_type in ('RECEIPT','ISSUE','ADJUSTMENT')),quantity_change integer not null check(quantity_change<>0),quantity_before integer not null check(quantity_before>=0),quantity_after integer not null check(quantity_after>=0),job_card_id uuid references public.job_cards(id),purchase_order_id uuid references public.purchase_orders(id),reference_number text,notes text,user_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.stock_out_exceptions(id uuid primary key default gen_random_uuid(),workshop_id uuid not null references public.workshops(id) on delete cascade,part_id uuid references public.parts(id),sku text,part_name text,job_card_id uuid references public.job_cards(id),job_number text,quantity_requested integer not null check(quantity_requested>0),reason_code text not null,detailed_reason text,responsible_person text,next_action text,expected_resolution_date date,status text not null default 'Open' check(status in ('Open','Resolved')),resolution_notes text,resolved_by uuid references auth.users(id),resolved_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.audit_events(id uuid primary key default gen_random_uuid(),workshop_id uuid not null references public.workshops(id) on delete cascade,event_type text not null,user_id uuid references auth.users(id),user_email text,reference_number text,sku text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists parts_workshop_name_idx on public.parts(workshop_id,name);create index if not exists parts_workshop_sku_idx on public.parts(workshop_id,sku);create index if not exists jobs_workshop_status_idx on public.job_cards(workshop_id,status);create index if not exists movements_workshop_date_idx on public.stock_movements(workshop_id,created_at desc);create index if not exists exceptions_workshop_status_idx on public.stock_out_exceptions(workshop_id,status);create index if not exists orders_workshop_status_idx on public.purchase_orders(workshop_id,status);
create or replace function public.current_workshop_id() returns uuid language sql stable security definer set search_path=public,pg_temp as $$ select workshop_id from public.workshop_memberships where user_id=auth.uid() and active order by created_at limit 1 $$;
create or replace function public.has_workshop_role(p_roles public.workshop_role[]) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.workshop_memberships m where m.user_id=auth.uid() and m.active and m.workshop_id=public.current_workshop_id() and m.role=any(p_roles)) $$;
create or replace function public.audit_event(p_workshop uuid,p_type text,p_reference text,p_sku text,p_details jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare v_email text; begin select email into v_email from auth.users where id=auth.uid(); insert into public.audit_events(workshop_id,event_type,user_id,user_email,reference_number,sku,details) values(p_workshop,p_type,auth.uid(),v_email,p_reference,p_sku,coalesce(p_details,'{}'::jsonb)); end $$;
create or replace function public.create_part(p_sku text,p_name text,p_description text,p_category text,p_opening_stock integer,p_unit_cost numeric,p_bin_location text,p_supplier_name text,p_supplier_contact text,p_avg_daily_demand numeric,p_lead_time_days integer,p_safety_stock integer,p_abc_class text,p_xyz_class text,p_minimum_order_qty integer,p_target_stock_level integer,p_manufacturer_reference text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare w uuid; pid uuid; begin w:=public.current_workshop_id(); if auth.uid() is null or w is null then raise exception 'No active workshop membership'; end if; if not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper']::public.workshop_role[]) then raise exception 'Permission denied to create parts'; end if; if p_opening_stock<0 or p_unit_cost<0 or p_avg_daily_demand<0 or p_lead_time_days<0 or p_safety_stock<0 then raise exception 'Quantities, cost, demand and lead time must be nonnegative'; end if; insert into public.parts(workshop_id,sku,name,description,category,current_stock,unit_cost,bin_location,supplier_name,supplier_contact,avg_daily_demand,lead_time_days,safety_stock,abc_class,xyz_class,minimum_order_qty,target_stock_level,manufacturer_reference,created_by) values(w,trim(p_sku),trim(p_name),p_description,p_category,p_opening_stock,p_unit_cost,p_bin_location,p_supplier_name,p_supplier_contact,p_avg_daily_demand,p_lead_time_days,p_safety_stock,p_abc_class,p_xyz_class,coalesce(p_minimum_order_qty,0),p_target_stock_level,p_manufacturer_reference,auth.uid()) returning id into pid; if p_opening_stock>0 then insert into public.stock_movements(workshop_id,part_id,sku,part_name,movement_type,quantity_change,quantity_before,quantity_after,reference_number,notes,user_id) select w,pid,sku,name,'RECEIPT',p_opening_stock,0,p_opening_stock,'OPENING STOCK','Opening quantity during part registration',auth.uid() from public.parts where id=pid; end if; perform public.audit_event(w,'PART_CREATED',p_sku,p_sku,jsonb_build_object('part_id',pid,'opening_stock',p_opening_stock)); return pid; end $$;
create or replace function public.update_part_details(p_part_id uuid,p_sku text,p_name text,p_description text,p_category text,p_unit_cost numeric,p_bin_location text,p_supplier_name text,p_supplier_contact text,p_avg_daily_demand numeric,p_lead_time_days integer,p_safety_stock integer,p_abc_class text,p_xyz_class text,p_minimum_order_qty integer,p_target_stock_level integer,p_manufacturer_reference text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare w uuid; p public.parts%rowtype; begin w:=public.current_workshop_id(); if w is null or not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper']::public.workshop_role[]) then raise exception 'Permission denied to edit part details'; end if; if p_unit_cost<0 or p_avg_daily_demand<0 or p_lead_time_days<0 or p_safety_stock<0 or p_minimum_order_qty<0 or (p_target_stock_level is not null and p_target_stock_level<0) then raise exception 'Part values must be nonnegative'; end if; select * into p from public.parts where id=p_part_id and workshop_id=w for update; if not found then raise exception 'Part not found in this workshop'; end if; update public.parts set sku=trim(p_sku),name=trim(p_name),description=p_description,category=p_category,unit_cost=p_unit_cost,bin_location=p_bin_location,supplier_name=p_supplier_name,supplier_contact=p_supplier_contact,avg_daily_demand=p_avg_daily_demand,lead_time_days=p_lead_time_days,safety_stock=p_safety_stock,abc_class=p_abc_class,xyz_class=p_xyz_class,minimum_order_qty=p_minimum_order_qty,target_stock_level=p_target_stock_level,manufacturer_reference=p_manufacturer_reference,updated_at=now() where id=p.id; perform public.audit_event(w,'PART_UPDATED',p.sku,p.sku,jsonb_build_object('part_id',p.id,'new_sku',p_sku)); end $$;
create or replace function public.create_job_card(p_job_number text,p_vehicle_identifier text,p_vehicle_model text,p_technician_identifier text,p_customer_reference text,p_card_type text,p_work_description text,p_notes text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare w uuid; jid uuid; st text; begin w:=public.current_workshop_id(); if w is null then raise exception 'No active workshop membership'; end if; if not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper','technician']::public.workshop_role[]) then raise exception 'Permission denied'; end if; if p_card_type not in ('Full','Provisional') then raise exception 'Invalid card type'; end if; if p_card_type='Full' and not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper']::public.workshop_role[]) then raise exception 'Only authorized staff can create full job cards'; end if; st:=case when p_card_type='Provisional' then 'Pending Approval' else 'Open' end; insert into public.job_cards(workshop_id,job_number,vehicle_identifier,vehicle_model,technician_identifier,customer_reference,card_type,status,created_by,work_description,notes) values(w,trim(p_job_number),trim(p_vehicle_identifier),p_vehicle_model,trim(p_technician_identifier),p_customer_reference,p_card_type,st,auth.uid(),p_work_description,p_notes) returning id into jid; perform public.audit_event(w,'JOB_CARD_CREATED',p_job_number,null,jsonb_build_object('job_card_id',jid,'card_type',p_card_type,'status',st)); return jid; end $$;
create or replace function public.approve_provisional_job_card(p_job_card_id uuid,p_reason text default null) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare j public.job_cards%rowtype; begin if not public.has_workshop_role(array['workshop_admin']::public.workshop_role[]) then raise exception 'Only a workshop administrator can approve provisional cards'; end if; select * into j from public.job_cards where id=p_job_card_id and workshop_id=public.current_workshop_id() for update; if not found or j.card_type<>'Provisional' or j.status<>'Pending Approval' then raise exception 'Provisional job card not found or not pending approval'; end if; update public.job_cards set status='Open',approved_by=auth.uid(),approved_at=now(),updated_at=now() where id=j.id; perform public.audit_event(j.workshop_id,'JOB_CARD_APPROVED',j.job_number,null,jsonb_build_object('job_card_id',j.id)); end $$;
create or replace function public.reject_provisional_job_card(p_job_card_id uuid,p_reason text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare j public.job_cards%rowtype; begin if not public.has_workshop_role(array['workshop_admin']::public.workshop_role[]) then raise exception 'Only a workshop administrator can reject provisional cards'; end if; select * into j from public.job_cards where id=p_job_card_id and workshop_id=public.current_workshop_id() for update; if not found or j.card_type<>'Provisional' or j.status<>'Pending Approval' then raise exception 'Provisional job card not found or not pending approval'; end if; update public.job_cards set status='Rejected',rejection_reason=p_reason,updated_at=now() where id=j.id; perform public.audit_event(j.workshop_id,'JOB_CARD_REJECTED',j.job_number,null,jsonb_build_object('job_card_id',j.id,'reason',p_reason)); end $$;
create or replace function public.receive_stock(p_sku text,p_quantity integer,p_supplier text,p_reference text,p_batch_reference text,p_bin_location text,p_notes text,p_purchase_order_id uuid default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare w uuid; p public.parts%rowtype; before_qty integer; after_qty integer; o public.purchase_orders%rowtype; add_qty integer; begin w:=public.current_workshop_id(); if auth.uid() is null or w is null then raise exception 'No active workshop membership'; end if; if not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper']::public.workshop_role[]) then raise exception 'Permission denied to receive stock'; end if; if p_quantity is null or p_quantity<=0 then raise exception 'Receipt quantity must be a positive integer'; end if; select * into p from public.parts where workshop_id=w and sku=trim(p_sku) for update; if not found then raise exception 'Unknown SKU'; end if; if p_purchase_order_id is not null then select * into o from public.purchase_orders where id=p_purchase_order_id and workshop_id=w for update; if not found or o.part_id<>p.id or o.status not in ('Ordered','Arrived') then raise exception 'Purchase order does not match this part or cannot be received'; end if; if p_quantity>o.ordered_qty-o.received_qty then raise exception 'Receipt quantity exceeds remaining purchase-order quantity'; end if; end if; before_qty:=p.current_stock; after_qty:=before_qty+p_quantity; update public.parts set current_stock=after_qty, supplier_name=coalesce(nullif(p_supplier,''),supplier_name),bin_location=coalesce(nullif(p_bin_location,''),bin_location),updated_at=now() where id=p.id; insert into public.stock_movements(workshop_id,part_id,sku,part_name,movement_type,quantity_change,quantity_before,quantity_after,reference_number,purchase_order_id,notes,user_id) values(w,p.id,p.sku,p.name,'RECEIPT',p_quantity,before_qty,after_qty,p_reference,p_purchase_order_id,concat_ws(' | ',p_batch_reference,p_notes),auth.uid()); if p_purchase_order_id is not null then add_qty:=p_quantity; update public.purchase_orders set received_qty=received_qty+add_qty,status=case when received_qty+add_qty>=ordered_qty then 'Received' else 'Arrived' end,updated_at=now() where id=o.id; end if; perform public.audit_event(w,'STOCK_RECEIVED',p_reference,p.sku,jsonb_build_object('quantity',p_quantity,'before',before_qty,'after',after_qty,'purchase_order_id',p_purchase_order_id)); return jsonb_build_object('new_stock',after_qty,'quantity_before',before_qty,'quantity_received',p_quantity); end $$;
create or replace function public.issue_stock(p_sku text,p_quantity integer,p_job_number text,p_technician_identifier text,p_notes text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare w uuid; p public.parts%rowtype; j public.job_cards%rowtype; before_qty integer; after_qty integer; begin w:=public.current_workshop_id(); if auth.uid() is null or w is null then raise exception 'No active workshop membership'; end if; if not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper']::public.workshop_role[]) then raise exception 'Permission denied to issue parts'; end if; if p_quantity is null or p_quantity<=0 then raise exception 'Issue quantity must be a positive integer'; end if; select * into j from public.job_cards where workshop_id=w and job_number=trim(p_job_number) for update; if not found then raise exception 'Job card not found'; end if; if j.status<>'Open' then raise exception 'Job card is not open and authorized'; end if; if j.card_type='Provisional' and j.approved_by is null then raise exception 'Provisional job card has not been approved'; end if; if j.technician_identifier<>trim(p_technician_identifier) then raise exception 'Technician does not match the job card'; end if; select * into p from public.parts where workshop_id=w and sku=trim(p_sku) for update; if not found then raise exception 'Unknown SKU'; end if; before_qty:=p.current_stock; if before_qty<p_quantity then raise exception 'Insufficient stock'; end if; after_qty:=before_qty-p_quantity; update public.parts set current_stock=after_qty,updated_at=now() where id=p.id; insert into public.stock_movements(workshop_id,part_id,sku,part_name,movement_type,quantity_change,quantity_before,quantity_after,job_card_id,reference_number,notes,user_id) values(w,p.id,p.sku,p.name,'ISSUE',-p_quantity,before_qty,after_qty,j.id,j.job_number,p_notes,auth.uid()); perform public.audit_event(w,'STOCK_ISSUED',j.job_number,p.sku,jsonb_build_object('quantity',p_quantity,'before',before_qty,'after',after_qty,'job_card_id',j.id)); return jsonb_build_object('new_stock',after_qty,'quantity_before',before_qty,'quantity_issued',p_quantity); end $$;
create or replace function public.create_purchase_order(p_order_number text,p_part_id uuid,p_supplier_name text,p_ordered_qty integer,p_expected_arrival_date date,p_reference_number text,p_notes text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare w uuid; p public.parts%rowtype; oid uuid; begin w:=public.current_workshop_id(); if w is null or not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper']::public.workshop_role[]) then raise exception 'Permission denied'; end if; if p_ordered_qty<=0 then raise exception 'Order quantity must be positive'; end if; select * into p from public.parts where id=p_part_id and workshop_id=w; if not found then raise exception 'Part not found in this workshop'; end if; insert into public.purchase_orders(workshop_id,order_number,part_id,supplier_name,ordered_qty,expected_arrival_date,reference_number,notes,created_by) values(w,trim(p_order_number),p_part_id,trim(p_supplier_name),p_ordered_qty,p_expected_arrival_date,p_reference_number,p_notes,auth.uid()) returning id into oid; perform public.audit_event(w,'PURCHASE_ORDER_CREATED',p_order_number,p.sku,jsonb_build_object('purchase_order_id',oid,'quantity',p_ordered_qty)); return oid; end $$;
create or replace function public.mark_order_arrived(p_order_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare o public.purchase_orders%rowtype; begin if not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper']::public.workshop_role[]) then raise exception 'Permission denied'; end if; select * into o from public.purchase_orders where id=p_order_id and workshop_id=public.current_workshop_id() for update; if not found or o.status<>'Ordered' then raise exception 'Order not found or not in Ordered status'; end if; update public.purchase_orders set status='Arrived',arrived_at=now(),updated_at=now() where id=o.id; perform public.audit_event(o.workshop_id,'ORDER_ARRIVED',o.order_number,null,jsonb_build_object('purchase_order_id',o.id,'stock_changed',false)); end $$;
create or replace function public.create_stock_out_exception(p_sku text,p_job_number text,p_quantity_requested integer,p_reason_code text,p_detailed_reason text,p_responsible_person text,p_next_action text,p_expected_resolution_date date) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare w uuid; p public.parts%rowtype; j public.job_cards%rowtype; eid uuid; begin w:=public.current_workshop_id(); if w is null then raise exception 'No active workshop membership'; end if; if p_quantity_requested<=0 then raise exception 'Requested quantity must be positive'; end if; select * into p from public.parts where workshop_id=w and sku=trim(coalesce(p_sku,'')); if p_job_number is not null then select * into j from public.job_cards where workshop_id=w and job_number=trim(p_job_number); if not found then raise exception 'Unknown job card'; end if; end if; insert into public.stock_out_exceptions(workshop_id,part_id,sku,part_name,job_card_id,job_number,quantity_requested,reason_code,detailed_reason,responsible_person,next_action,expected_resolution_date,created_by) values(w,p.id,coalesce(p.sku,p_sku),p.name,j.id,j.job_number,p_quantity_requested,p_reason_code,p_detailed_reason,p_responsible_person,p_next_action,p_expected_resolution_date,auth.uid()) returning id into eid; perform public.audit_event(w,'STOCK_OUT_EXCEPTION_CREATED',p_job_number,p_sku,jsonb_build_object('exception_id',eid,'reason',p_reason_code)); return eid; end $$;
create or replace function public.resolve_stock_out_exception(p_exception_id uuid,p_resolution_notes text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare x public.stock_out_exceptions%rowtype; begin if not public.has_workshop_role(array['workshop_admin','inventory_manager','storekeeper']::public.workshop_role[]) then raise exception 'Permission denied'; end if; select * into x from public.stock_out_exceptions where id=p_exception_id and workshop_id=public.current_workshop_id() for update; if not found or x.status<>'Open' then raise exception 'Open exception not found'; end if; update public.stock_out_exceptions set status='Resolved',resolution_notes=p_resolution_notes,resolved_by=auth.uid(),resolved_at=now() where id=x.id; perform public.audit_event(x.workshop_id,'STOCK_OUT_EXCEPTION_RESOLVED',x.job_number,x.sku,jsonb_build_object('exception_id',x.id)); end $$;
-- One-time bootstrap: run as project owner in SQL Editor after the first user signs up. Replace both placeholders.
-- This function intentionally is NOT executable by authenticated browser users.
create or replace function public.bootstrap_first_workshop(p_user_id uuid,p_workshop_name text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare wid uuid; begin if exists(select 1 from public.workshop_memberships) then raise exception 'Bootstrap is only available before any workshop membership exists'; end if; if not exists(select 1 from auth.users where id=p_user_id) then raise exception 'Auth user not found'; end if; insert into public.workshops(name) values(trim(p_workshop_name)) returning id into wid; insert into public.workshop_memberships(workshop_id,user_id,role) values(wid,p_user_id,'workshop_admin'); insert into public.profiles(id,email) select id,email from auth.users where id=p_user_id on conflict(id) do update set email=excluded.email; return wid; end $$;
revoke all on function public.bootstrap_first_workshop(uuid,text) from public,anon,authenticated;
revoke all on function public.audit_event(uuid,text,text,text,jsonb) from public,anon,authenticated;
revoke all on function public.current_workshop_id() from public,anon;grant execute on function public.current_workshop_id() to authenticated;
revoke all on function public.has_workshop_role(public.workshop_role[]) from public,anon;grant execute on function public.has_workshop_role(public.workshop_role[]) to authenticated;
grant execute on function public.create_part(text,text,text,text,integer,numeric,text,text,text,numeric,integer,integer,text,text,integer,integer,text) to authenticated;grant execute on function public.update_part_details(uuid,text,text,text,text,numeric,text,text,text,numeric,integer,integer,text,text,integer,integer,text) to authenticated;grant execute on function public.create_job_card(text,text,text,text,text,text,text,text) to authenticated;grant execute on function public.approve_provisional_job_card(uuid,text) to authenticated;grant execute on function public.reject_provisional_job_card(uuid,text) to authenticated;grant execute on function public.receive_stock(text,integer,text,text,text,text,text,uuid) to authenticated;grant execute on function public.issue_stock(text,integer,text,text,text) to authenticated;grant execute on function public.create_purchase_order(text,uuid,text,integer,date,text,text) to authenticated;grant execute on function public.mark_order_arrived(uuid) to authenticated;grant execute on function public.create_stock_out_exception(text,text,integer,text,text,text,text,date) to authenticated;grant execute on function public.resolve_stock_out_exception(uuid,text) to authenticated;
-- RLS: all business data is shared by active members of a workshop, not per-user.
do $$ declare t text; begin foreach t in array array['workshops','profiles','workshop_memberships','parts','job_cards','purchase_orders','stock_movements','stock_out_exceptions','audit_events'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy workshops_read_member on public.workshops for select to authenticated using(id=public.current_workshop_id());
create policy profiles_read_self on public.profiles for select to authenticated using(id=auth.uid());create policy profiles_update_self on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy memberships_read_same on public.workshop_memberships for select to authenticated using(workshop_id=public.current_workshop_id());
create policy parts_read on public.parts for select to authenticated using(workshop_id=public.current_workshop_id());
-- No direct UPDATE policy on parts: all editable fields go through update_part_details; current_stock only changes in audited stock RPCs.
create policy jobs_read on public.job_cards for select to authenticated using(workshop_id=public.current_workshop_id());create policy orders_read on public.purchase_orders for select to authenticated using(workshop_id=public.current_workshop_id());create policy exceptions_read on public.stock_out_exceptions for select to authenticated using(workshop_id=public.current_workshop_id());create policy movements_read on public.stock_movements for select to authenticated using(workshop_id=public.current_workshop_id());create policy audit_read on public.audit_events for select to authenticated using(workshop_id=public.current_workshop_id() and public.has_workshop_role(array['workshop_admin','inventory_manager','auditor']::public.workshop_role[]));
-- No direct INSERT/UPDATE/DELETE policies for stock movements or audit events: writes happen only inside RPCs.
-- Staff membership administration must be performed by project owner/admin tooling; no self-promotion policy is provided.


-- Admin-only part deletion. Existing movement/order history is protected.
create or replace function public.admin_delete_part(p_part_id uuid) returns void
language plpgsql security definer set search_path=public,pg_temp as $$
declare w uuid; p public.parts%rowtype;
begin
 w:=public.current_workshop_id();
 if auth.uid() is null or w is null or not public.has_workshop_role(array['workshop_admin']::public.workshop_role[]) then raise exception 'Only a workshop administrator can delete parts'; end if;
 select * into p from public.parts where id=p_part_id and workshop_id=w for update;
 if not found then raise exception 'Part not found in this workshop'; end if;
 if p.current_stock<>0 then raise exception 'Cannot delete a part with stock remaining. Use controlled adjustment first.'; end if;
 if exists(select 1 from public.stock_movements where part_id=p.id) or exists(select 1 from public.purchase_orders where part_id=p.id) then raise exception 'Part has movement/order history and cannot be deleted.'; end if;
 perform public.audit_event(w,'PART_DELETED',p.sku,p.sku,jsonb_build_object('part_id',p.id,'part_name',p.name));
 delete from public.parts where id=p.id;
end $$;
revoke all on function public.admin_delete_part(uuid) from public,anon;
grant execute on function public.admin_delete_part(uuid) to authenticated;


-- Return technician accounts for the signed-in user's active workshop only.
-- The UID is the canonical selectable technician code; manual codes remain allowed by the UI.
create or replace function public.list_workshop_technicians()
returns table(technician_code text, display_label text)
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare w uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  w := public.current_workshop_id();
  if w is null then raise exception 'No active workshop membership'; end if;
  return query
    select m.user_id::text,
           coalesce(nullif(trim(pr.display_name),''), nullif(trim(m.email),''), m.user_id::text)
    from public.workshop_memberships m
    left join public.profiles pr on pr.id=m.user_id
    left join auth.users au on au.id=m.user_id
    where m.workshop_id=w and m.active and m.role='technician'::public.workshop_role
    order by coalesce(nullif(trim(pr.display_name),''), nullif(trim(au.email),''), m.user_id::text);
end $$;
revoke all on function public.list_workshop_technicians() from public, anon;
grant execute on function public.list_workshop_technicians() to authenticated;
